import { REPO_ROOT } from "../_shared/deno-helpers.ts";

const NPX = Deno.build.os === "windows" ? "npx.cmd" : "npx";
const NODE = Deno.build.os === "windows" ? "node.exe" : "node";

for (const [label, cmd, args] of [
  ["node -v", NODE, ["-v"]],
  ["npm -v", Deno.build.os === "windows" ? "npm.cmd" : "npm", ["-v"]],
] as const) {
  const { stdout } = await new Deno.Command(cmd, { args, cwd: REPO_ROOT, stdout: "piped" }).output();
  console.log(label, "->", new TextDecoder().decode(stdout).trim());
}

// Read the real config file's text so you can see those two lines from right here too,
// without leaving the notebook. This is plain file reading — nothing Playwright-specific.
// (REPO_ROOT is already imported above — the Deno kernel shares one module scope
// across every cell in a notebook, so importing it twice would clash.)
const configText = await Deno.readTextFile(REPO_ROOT + "playwright.config.ts");
const testMatchLine = configText.split("\n").find((l) => l.includes("testMatch:"));
// Look for "baseURL:" (with the colon) — the file also has a comment that mentions
// "baseURL" in passing, and a plain .includes("baseURL") would match that instead.
const baseUrlLine = configText.split("\n").find((l) => l.includes("baseURL:"));

console.log(testMatchLine?.trim());
console.log(baseUrlLine?.trim());

// REPO_ROOT is already imported in the first code cell above — reused here.
try {
  const entries = [...Deno.readDirSync(REPO_ROOT + "week1/generated")];
  console.log("week1/generated exists already, contains:", entries.map((e) => e.name));
} catch (err) {
  console.log("week1/generated does not exist yet:", (err as Error).message.split("\n")[0]);
}

// The shape of the choice, as data — not runnable Playwright, just the config option itself.
const freshScaffold = { testDir: "./tests" };
const splitByType = { testDir: "./", testMatch: ["UI_test/**/*.spec.ts", "API_test/**/*.spec.ts"] };
const thisRepo = { testDir: "./", testMatch: ["week*/**/*.spec.ts"] };

console.log("fresh scaffold:", JSON.stringify(freshScaffold));
console.log("split by type: ", JSON.stringify(splitByType));
console.log("this repo:     ", JSON.stringify(thisRepo));

import { REPO_ROOT } from "../_shared/deno-helpers.ts";

const gitignore = await Deno.readTextFile(REPO_ROOT + ".gitignore");
for (const needle of ["node_modules", "test-results", "playwright-report"]) {
  console.log(needle, "->", gitignore.includes(needle) ? "present" : "MISSING");
}

problems.solution:
In the studio the code runs in Node, so the versions come from `process`:

```ts
console.log('node ' + process.version);
console.log('v8   ' + process.versions.v8);
// node v20.11.0
// v8   11.3.244.8-node.17
```

npm is a separate binary rather than part of the runtime, so it has no `process.versions` entry — read it from your own terminal with `npm -v` and note it in a comment.

**What good looks like:** two real numbers off *your* machine. The reason the lesson asks is that "works on my machine" is a version story more often than a code story — when a colleague's scaffold behaves differently, the first question is which Node they are on.

> Playwright needs Node 18+; the course was built on Node 20. If yours is older, that is worth fixing before Week 3.
